def filter_dataframes(dataframes):
    filtered = {}
    for filename, df in dataframes.items():
        if filename == 'sales_pipeline.csv' and 'channel' in df.columns:
            # Remove linhas onde o canal é 'Partner' (case-insensitive)
            filtered[filename] = df[df['channel'].str.lower() != 'partner'].copy()
        else:
            filtered[filename] = df.copy()
    return filtered
